      "target": "C2",
      "layers": [
        {
          "layer_id": "RV-PATH-EA425A",
          "applies": true,
          "reason": "The scenario is pressure build-up in the EA-425A tube side due to a closed outlet valve (m:S-L-QW-A-OUT:more:pressure) with continued heat input; the PRV on EA-425A is sized for this overpressure scenario and would open before tube rupture."
        }
      ]
    },
    {
      "target": "C3",
      "layers": [
        {
          "layer_id": "RV-PATH-EA425B",
          "applies": false,
          "reason": "The scenario is a piping leak on L-A-SIN releasing hydrocarbons to the Olefins unit (m:S-L-A-SIN:less:flow) with potential ignition; the PRV on EA-425B protects only against overpressure in EA-425B and does not detect or mitigate a piping release or external fire."
        }
      ]
    },
    {
      "target": "C4",
      "layers": [
        {
          "layer_id": "RV-PATH-EA425B",
          "applies": true,
          "reason": "The scenario isolates the EA-425B shell side with heat input during startup (m:S-EA-425B:no:flow), causing pressure rise and tube rupture; the PRV on EA-425B is sized for this overpressure scenario and would relieve pressure before rupture."
        }
      ]
    },
    {
      "target": "C5",
      "layers": [
        {
          "layer_id": "RV-PATH-EA425B",
          "applies": false,
          "reason": "The scenario is hydrocarbon ingress into the quench-water loop after a tube rupture on standby EA-425B (m:S-EA-425B:as_well_as:composition), creating a latent fire hazard; the PRV on EA-425B acts only on overpressure of EA-425B, not on composition change or fire hazard in the quench loop."
        }
      ]
    }
  ]
}

